//! Lumia's design tokens (`assets/design/tokens.json`) as Rune values, generated by `build.rs`:
//! [`Colors`] for light and dark, the spacing, radii and sizes as points, the type styles, the
//! fonts. Views take every colour, distance and type style from here; a literal in a view is
//! a value the design system does not know about.

use rune::{Color, Family, Shadow, TextStyle};
use rune_kit::syntax::{Syntax, SyntaxTheme};

/// The display family's name inside the font files: titles and monograms only.
const DISPLAY: Family = Family::Named("Bricolage Grotesque");

include!(concat!(env!("OUT_DIR"), "/tokens.rs"));

/// The sans and mono slots. `ui-monospace` is the platform's own, since the design system
/// ships no monospaced face.
pub const FAMILIES: (&str, &str) = ("Albert Sans", "ui-monospace");

pub fn colors(dark: bool) -> &'static Colors {
    if dark { &DARK } else { &LIGHT }
}

pub fn shadows(dark: bool) -> &'static Shadows {
    if dark { &DARK_SHADOWS } else { &LIGHT_SHADOWS }
}

/// The nine tones, ground and ink, in `lumia_client::rail::TONES`' order.
fn tones(c: &Colors) -> [(Color, Color); 9] {
    [
        (c.tone_peach, c.tone_peach_ink),
        (c.tone_blue, c.tone_blue_ink),
        (c.tone_purple, c.tone_purple_ink),
        (c.tone_mint, c.tone_mint_ink),
        (c.tone_amber, c.tone_amber_ink),
        (c.tone_sky, c.tone_sky_ink),
        (c.tone_stone, c.tone_stone_ink),
        (c.tone_green, c.tone_green_ink),
        (c.tone_indigo, c.tone_indigo_ink),
    ]
}

/// The avatar ground and ink an id hashes to: the web's `toneFor` and LumiaKit's
/// `AvatarTone.of`, so a person is the same colour on every client.
pub fn tone(id: &str, c: &Colors) -> (Color, Color) {
    tones(c)[lumia_client::rail::tone_index(id)]
}

/// The ground and ink of a tone by its name (a rail folder's); peach for one not known.
pub fn tone_named(name: &str, c: &Colors) -> (Color, Color) {
    let at = lumia_client::rail::TONES
        .iter()
        .position(|tone| *tone == name)
        .unwrap_or(0);
    tones(c)[at]
}

// ---- What the boards draw that the design system names only in a usage line, or not at all --
//
// Each is arithmetic on tokens, so a view holds no literal; the board's own number is beside
// it. Where the tokens cannot make the number, the nearest token stands in and the comment
// says so. All of them are gaps in `tokens.json`.

/// A scroll bar's thumb, at rest and under the pointer or held. The design system names no
/// colour for one (the boards have the browser's own): the composer's focused border at
/// rest, which is the quietest line that still reads on `surface` and `bg`, and the ink of
/// a timestamp while it is held.
pub fn scroll_thumb(c: &Colors) -> (Color, Color) {
    (c.border_active, c.ink_muted)
}

